import {createClient} from '@supabase/supabase-js';
import {icon,modules,ar} from './ui.js';
import './styles.css';
import './contrast.css';
const cfg=window.QUALITY_CONFIG;
if(window.top!==window.self){document.body.textContent='Open this workspace directly in your browser.';throw new Error('Embedded workspace blocked');}
const db=createClient(cfg.url,cfg.anonKey,{auth:{persistSession:true,storage:sessionStorage,autoRefreshToken:true,detectSessionInUrl:false}});
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang=localStorage.getItem('quality-language')||'en';
const t=s=>lang==='ar'?(ar[s]||s):s;
const mname=k=>modules[k]?.[lang]||k;
const n=v=>Number(v||0).toLocaleString(lang==='ar'?'ar-AE':'en-GB');
const pct=v=>v==null?'—':Number(v).toLocaleString(lang==='ar'?'ar-AE':'en-GB',{maximumFractionDigits:1})+'%';
const date=v=>v?new Date(v.length===10?v+'T12:00:00':v).toLocaleDateString(lang==='ar'?'ar-AE':'en-GB',{day:'numeric',month:'short',year:'numeric'}):t('No date set');
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Dubai'});
const color=v=>/^#[0-9a-f]{6}$/i.test(v||'')?v:'#879acc';
const stateNames={open:'Open',closed:'Closed',review:'Under review',other:'Other',void:'Void',superseded:'Superseded'};
const statusPill=(state,label)=>`<span class="pill ${{open:'red',review:'amber',closed:'green',void:'',superseded:'purple'}[state]||''}">${esc(label||t(stateNames[state]||'Other'))}</span>`;
let S={profile:null,projects:[],stats:[],updates:[],page:'overview',project:null,tab:'overview',category:'site_rfi',search:'',filter:'active',list:false,recordSearch:'',recordState:'',currentOnly:true,recordPage:0,records:[],recordCount:0,users:[],members:[],history:[],busy:false};
let renderTicket=0,recordsTicket=0;
const admin=()=>S.profile?.role==='admin';
const project=()=>S.projects.find(p=>p.id===S.project);
const stats=(pid,cat)=>S.stats.filter(x=>(!pid||x.project_id===pid)&&(!cat||x.category===cat));
const sum=(list,key)=>list.reduce((a,x)=>a+Number(x[key]||0),0);
const statVal=(pid,cat,key='open')=>sum(stats(pid,cat),key);
const btn=(text,act,ic='',type='')=>`<button class="btn ${type}" data-action="${act}">${ic?icon(ic):''}${esc(t(text))}</button>`;
const brand=()=>`<div class="brand row"><span class="brand-mark">${icon('grid')}</span><span class="brand-name">Quality<span style="font-weight:400">Hub</span><small>PROJECT WORKSPACE</small></span></div>`;
const empty=(title,sub,ic='folder')=>`<div class="empty">${icon(ic)}<h3>${esc(t(title))}</h3><p>${esc(t(sub))}</p></div>`;
const field=(label,name,value='',type='text',extra='')=>`<label class="field ${extra.includes('full')?'full':''}"><span>${esc(t(label))}</span><input name="${name}" type="${type}" value="${esc(value??'')}" ${extra.replace('full','')}></label>`;
const textfield=(label,name,value='',extra='')=>`<label class="field full"><span>${esc(t(label))}</span><textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
const select=(label,name,options,value='',extra='')=>`<label class="field"><span>${esc(t(label))}</span><select name="${name}" ${extra}>${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t(l))}</option>`).join('')}</select></label>`;
function toast(msg,error=false){$('.toast')?.remove();const d=document.createElement('div');d.className='toast'+(error?' error':'');d.role=error?'alert':'status';d.textContent=t(msg);document.body.append(d);setTimeout(()=>d.remove(),5500);}
function setLanguage(){lang=lang==='en'?'ar':'en';localStorage.setItem('quality-language',lang);document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';if(S.profile)render();else login();}
function modal(title,sub,body,onSubmit,wide=false){$('.modal-backdrop')?.remove();const before=document.activeElement;const w=document.createElement('div');w.className='modal-backdrop';w.innerHTML=`<section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(t(title))}"><div class="modal-head"><div><h2>${esc(t(title))}</h2><p>${esc(t(sub))}</p></div><button class="modal-close" data-close aria-label="Close">${icon('close')}</button></div><form>${body}<div class="form-error hidden" role="alert"></div></form></section>`;document.body.append(w);const close=()=>{w.remove();before?.focus()};w.close=close;w.addEventListener('click',e=>{if(e.target===w||e.target.closest('[data-close]'))close()});w.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const f=$$('button,input,select,textarea,a[href]',w).filter(x=>!x.disabled&&x.offsetParent!==null);if(!f.length)return;const first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});$('form',w).addEventListener('submit',async e=>{e.preventDefault();if(!onSubmit)return;const form=e.target,submit=$('[type=submit]',form),err=$('.form-error',form);err.classList.add('hidden');if(submit)submit.disabled=true;try{await onSubmit(new FormData(form),w,form);}catch(e){err.textContent=e.message||'Could not save. Please try again.';err.classList.remove('hidden')}finally{if(submit)submit.disabled=false;}});setTimeout(() => ($('input,select,textarea',w)||$('[data-close]',w))?.focus(),40);return w;}
const actions=(save='Save',extra='')=>`<div class="form-actions">${extra}<button type="button" class="btn" data-close>${t('Cancel')}</button><button type="submit" class="btn primary">${esc(t(save))}</button></div>`;
async function check(result){const r=await result;if(r.error)throw Error(r.error.message);return r.data;}
function login(error=''){
 document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';
 $('#app').innerHTML=`<main class="login-page"><button class="lang-btn" data-action="language">${lang==='en'?'العربية':'English'}</button><section class="login-art">${brand()}<div class="login-art-inner"><div class="eyebrow">${esc(t('Project workspace'))}</div><h1>${esc(t('A clearer way to manage project quality.'))}</h1><p>${esc(t('One connected workspace for progress, quality registers and the people who need to see them.'))}</p><div class="preview-stack">${[['folder','Project control','Organized by project'],['chart','Linked registers','One source of truth'],['shield','Private access','Admin controlled']].map(([i,a,b])=>`<div class="preview-tile">${icon(i)}<strong>${esc(t(a))}</strong><small>${esc(t(b))}</small></div>`).join('')}</div></div></section><section class="login-form-wrap"><form class="login-form" id="login-form"><span class="pill blue">${icon('lock')}${esc(t('Private workspace'))}</span><h2>${esc(t('Welcome back'))}</h2><p>${esc(t('Enter the login your administrator gave you.'))}</p>${field('Username','username','','text','required autocomplete="username" autocapitalize="none" spellcheck="false" maxlength="40"')}${field('Password','password','','password','required autocomplete="current-password" maxlength="128"')}<div class="login-error ${error?'form-error':'hidden'}" role="alert">${esc(error)}</div><button class="btn primary" type="submit">${esc(t('Sign in'))}${icon('arrow')}</button><div class="lock-note">${icon('shield')}<span>${esc(t('No public registration. Ask your administrator for an account or a password reset.'))}</span></div></form><div class="login-footer">© Abdelrahman Hamdy · QualityHub</div></section></main>`;
 $('#login-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),user=String(f.get('username')).trim().toLowerCase(),pass=String(f.get('password'));const b=$('[type=submit]',e.target),err=$('.login-error');b.disabled=true;b.textContent=t('Signing in…');err.classList.add('hidden');try{if(!/^[a-z0-9][a-z0-9._-]{2,39}$/.test(user))throw Error(t('Sign-in failed. Check your username and password.'));const r=await db.auth.signInWithPassword({email:user+'@quality-hub.internal',password:pass});if(r.error)throw Error(t('Sign-in failed. Check your username and password.'));e.target.reset();await enter();}catch(x){err.textContent=x.message;err.className='login-error form-error';b.disabled=false;b.innerHTML=esc(t('Sign in'))+icon('arrow');}};
}
async function enter(){
 $('#app').innerHTML=`<div class="loading"><div class="spinner"></div><span>${esc(t('Loading…'))}</span></div>`;
 const {data:{user}}=await db.auth.getUser();if(!user){login();return}
 try{S.profile=await check(db.from('profiles').select('*').eq('id',user.id).single());if(!S.profile.active){await db.auth.signOut();S.profile=null;login(t('Your account is disabled. Contact your administrator.'));return}await loadData();await render();}catch(e){S.profile=null;await db.auth.signOut();login(e.message);}
}
async function loadData(){const [projects,st,up]=await Promise.all([check(db.from('projects').select('*').order('code')),check(db.rpc('dashboard_stats')),check(db.from('project_updates').select('*').order('created_at',{ascending:false}).limit(8))]);S.projects=projects;S.stats=st||[];S.updates=up;if(S.project&&!project()){S.project=null;S.page='overview'};}
function shell(content){const names={overview:'Overview',projects:'Projects',insights:'Insights',workload:'Inspector Workload',users:'User management',activity:'Activity log'};const initial=(S.profile.full_name||S.profile.username).split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase();return `<aside class="sidebar">${brand()}<div class="nav-label">${esc(t('Workspace'))}</div>${[['overview','grid','Overview'],['projects','folder','Projects'],['insights','chart','Insights'],['workload','users','Inspector Workload']].map(([p,i,l])=>`<button class="nav-item ${S.page===p?'active':''}" data-page="${p}">${icon(i)}<span>${esc(t(l))}</span>${p==='projects'?`<span class="nav-count">${S.projects.filter(p=>!p.archived).length}</span>`:''}</button>`).join('')}${admin()?`<div class="nav-label">${esc(t('Administration'))}</div>${[['users','users','User management'],['activity','history','Activity log']].map(([p,i,l])=>`<button class="nav-item ${S.page===p?'active':''}" data-page="${p}">${icon(i)}<span>${esc(t(l))}</span></button>`).join('')}`:''}<div class="side-bottom"><div class="secure-note">${icon('shield')}<br><b>${esc(t('Private workspace'))}</b><br>${esc(t('Project access is controlled by your administrator.'))}</div><div class="account row"><span class="avatar">${esc(initial)}</span><div class="grow"><strong>${esc(S.profile.full_name||S.profile.username)}</strong><small>${esc(t(admin()?'Administrator':'Viewer'))}</small></div><button class="logout-btn" title="${t('Sign out')}" data-action="logout">${icon('logout')}</button></div></div></aside><div class="shell"><header class="topbar"><div class="row"><button class="mobile-menu btn icon" data-action="menu" aria-label="Menu">${icon('menu')}</button><div class="crumb"><span class="root-crumb">${esc(t('Workspace'))} &nbsp; / &nbsp; </span><b>${esc(S.project?project()?.code:t(names[S.page]||'Overview'))}</b>${S.project?` &nbsp; / &nbsp; ${esc(t(S.tab==='records'?'Registers':'Project overview'))}`:''}</div></div><div class="row top-actions"><span class="top-date">${esc(date(today()))}</span><span class="pill green"><i class="dot"></i>${esc(t('Connected'))}</span><button class="lang-top" data-action="language">${lang==='en'?'العربية':'English'}</button><button class="btn icon" data-action="account" title="${t('Your account')}">${icon('users')}</button></div></header><main class="content" id="main">${content}<footer class="footer"><span>© Abdelrahman Hamdy · QualityHub</span><span>${esc(t('Internal project data'))} · ${esc(t('Project workspace'))}</span></footer></main></div>`;}
function statCard(label,value,sub,ic){return `<div class="stat"><div class="stat-top"><span>${esc(t(label))}</span><span class="stat-icon">${icon(ic)}</span></div><div class="stat-value">${esc(value)}</div><div class="stat-bottom">${esc(t(sub))}</div></div>`;}
function hero(title,subtitle,buttons='',eyebrow='Project workspace'){return `<div class="hero row spread wrap"><div><div class="eyebrow">${esc(t(eyebrow))}</div><h1>${esc(t(title))}</h1><p>${esc(t(subtitle))}</p></div><div class="row hero-actions">${buttons}</div></div>`;}
function progressChart(ps){return `<div class="chart-wrap"><div class="chart"><div class="chart-y"><span>100%</span><span>75%</span><span>50%</span><span>25%</span><span>0%</span></div>${ps.slice(0,10).map(p=>`<button class="bar-column" data-project="${p.id}" aria-label="${esc(p.code+' '+pct(p.actual))}"><span class="bar-value">${esc(pct(p.actual))}</span><i class="bar-fill" style="height:${Math.max(0,Math.min(100,Number(p.actual)||0))}%;background:${color(p.color)}"></i><span class="bar-label">${esc(p.code)}</span></button>`).join('')}</div></div>`;}
function updatesList(){return S.updates.length?S.updates.slice(0,4).map(u=>{const p=S.projects.find(p=>p.id===u.project_id);return `<div class="activity-item"><span class="activity-icon">${icon('chart')}</span><div class="grow"><strong>${esc(p?.code||'')} · ${esc(pct(u.actual))}</strong><p>${esc(u.note.slice(0,65)||t('Progress'))}</p></div><span class="activity-date">${esc(date(u.as_of))}</span></div>`}).join(''):empty('No recent activity','Updates will appear here.','history');}
function projectCard(p){const rf=statVal(p.id,'site_rfi'),nc=statVal(p.id,'findings'),dc=statVal(p.id,'docs')+statVal(p.id,'docs','review');return `<article class="project-card" data-project="${p.id}" style="--pc:${color(p.color)}" role="button" tabindex="0"><div class="row spread"><span class="project-glyph">${icon('building')}</span><span class="project-code">${esc(p.code)}</span><span class="pill ${p.archived?'':p.stage.toLowerCase().includes('close')?'purple':'green'}"><i class="dot"></i>${esc(p.archived?t('Archived'):t(p.stage))}</span></div><div><h3 class="project-title">${esc(p.name)}</h3><div class="project-meta"><span>${esc(p.number||p.code)}</span><span>${esc(p.contractor||'—')}</span></div></div><div><div class="progress-row"><span>${esc(t('Progress'))}</span><b>${esc(pct(p.actual))}</b></div><div class="track"><i style="width:${Math.min(100,Number(p.actual)||0)}%"></i></div></div><div class="card-metrics"><div><strong style="color:#8394c4">${n(rf)}</strong><span>${esc(t('Open RFIs'))}</span></div><div><strong style="color:#c18d9d">${n(nc)}</strong><span>NCR / CAR</span></div><div><strong style="color:#b5a070">${n(dc)}</strong><span>${esc(t('Documents pending'))}</span></div></div><div class="card-footer"><span>${esc(t('Progress as of'))} ${esc(date(p.as_of))}</span><span class="card-arrow">${icon('arrow')}</span></div></article>`;}
function portfolio(full=false){const active=S.projects.filter(p=>!p.archived),withProgress=active.filter(p=>p.actual!=null),avg=withProgress.length?withProgress.reduce((a,p)=>a+Number(p.actual),0)/withProgress.length:null;const ps=S.projects.filter(p=>(S.filter==='all'||S.filter==='archived'?S.filter==='all'||p.archived:!p.archived)&&(`${p.code} ${p.name} ${p.contractor} ${p.number}`.toLowerCase().includes(S.search.toLowerCase())));return hero(full?'Projects':'Your projects. One clear view.',full?'Data stays linked to its project.':'Keep quality, progress and your team connected.',btn('Refresh','refresh','refresh')+(admin()?btn('New project','new-project','plus','primary'):''))+(S.projects.some(p=>p.source_label)?`<div class="notice">${icon('calendar')}<span>${lang==='ar'?'البيانات المستوردة لقطة من الملف المرفوع، وليست تحديثا تلقائيا من المقاولين. الأرقام تعتمد على أحدث حالة محفوظة والمراجعات الحالية، وقد تختلف عن حسابات تاريخ القطع في الملف الأصلي.':'Imported data is a snapshot of the uploaded file, not an automatic contractor feed. Counts use current revisions and latest stored status, so they can differ from the original historical cut-off calculations.'}</span></div>`:'')+(full?'':`<div class="stats">${statCard('Visible projects',n(active.length),'For assigned projects','folder')}${statCard('Open RFIs',n(statVal(null,'site_rfi')),'Current revisions only','eye')}${statCard('Open NCR / CAR',n(statVal(null,'findings')),'Current register status','alert')}${statCard('Average progress',pct(avg),'Actual','chart')}</div>${active.length?`<div class="overview-row"><section class="panel panel-pad"><div class="section-head"><div><h2>${esc(t('Project progress'))}</h2><small>${esc(t('Latest updates'))}</small></div><span class="pill blue">${esc(t('Actual'))} %</span></div>${progressChart(active)}</section><section class="panel panel-pad recent-panel"><div class="section-head"><h2>${esc(t('Latest updates'))}</h2><span class="pill">${esc(t('In sync'))}</span></div><div class="recent-list">${updatesList()}</div></section></div>`:''}`)+`<div class="section-head"><div class="row"><h2 class="section-title">${esc(t('All projects'))}</h2><span class="pill">${n(ps.length)}</span></div><div class="filter-row"><div class="searchbox">${icon('search')}<input id="project-search" aria-label="${t('Search projects…')}" placeholder="${t('Search projects…')}" value="${esc(S.search)}"></div><select id="project-filter" class="input" style="width:auto;min-height:39px;padding:8px;font-size:10px" aria-label="Project status"><option value="active" ${S.filter==='active'?'selected':''}>${t('Active')}</option><option value="archived" ${S.filter==='archived'?'selected':''}>${t('Archived')}</option><option value="all" ${S.filter==='all'?'selected':''}>${t('All')}</option></select><div class="segmented"><button class="${!S.list?'on':''}" data-action="grid-view" aria-label="Grid view">${icon('grid')}</button><button class="${S.list?'on':''}" data-action="list-view" aria-label="List view">${icon('list')}</button></div></div></div><div class="projects ${S.list?'list-view':''}" id="project-grid">${ps.map(projectCard).join('')}${admin()?`<button class="project-card add-card" data-action="new-project"><span class="plus">+</span><b>${esc(t('Add new project'))}</b><p>${esc(t('Create a home for your next project.'))}</p></button>`:''}</div>${!ps.length?empty(S.projects.length?'No matching projects':'No projects available',S.projects.length?'Try another search.':'Your administrator will grant access to your projects.') :''}`;}
function projectHeader(p){return `<button class="btn" style="margin-bottom:20px" data-action="back-projects">${icon('back')}${t('Back to projects')}</button><section class="panel project-banner"><div class="ring"><svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="43" stroke="#f0f2f8" stroke-width="6" fill="none"/><circle cx="50" cy="50" r="43" stroke="${color(p.color)}" stroke-width="6" fill="none" stroke-linecap="round" stroke-dasharray="${2.702*(Number(p.actual)||0)} 270.2"/></svg><b>${esc(pct(p.actual))}</b></div><div class="grow"><span class="eyebrow">${esc(p.code)} · ${esc(p.number)}</span><h2>${esc(p.name)}</h2><p>${esc(p.contractor)}${p.contract?' · '+esc(p.contract):''} · ${esc(t(p.stage))}</p><p>${esc(t('Progress as of'))} ${esc(date(p.as_of))}</p></div><div class="row wrap">${admin()?btn('Edit project','edit-project','edit')+btn('Post update','post-update','plus','primary'):`<span class="pill blue">${icon('eye')}${t('Read-only')}</span>`}</div></section><div class="tabs">${[['overview','Project overview'],['records','Registers'],['workload','Inspector Workload'],['progress','Progress history']].map(([id,l])=>`<button class="${S.tab===id?'on':''}" data-tab="${id}">${esc(t(l))}</button>`).join('')}</div>`;}
function projectOverview(p){const total=sum(stats(p.id),'total'),open=sum(stats(p.id),'open'),overdue=sum(stats(p.id),'overdue');return `<div class="notice">${icon('calendar')}<span>${esc(t('Reporting snapshot'))}: ${esc(p.source_label||date(p.as_of))}. ${esc(p.note)}</span></div><div class="stats">${statCard('Register records',n(total),'Current revisions only','file')}${statCard('Open RFIs',n(statVal(p.id,'site_rfi')),'Current register status','eye')}${statCard('Open NCR / CAR',n(statVal(p.id,'findings')),'Current register status','alert')}${statCard('Open punch items',n(statVal(p.id,'punch')),'Current register status','list')}</div><div class="section-head"><h2 class="section-title">${esc(t('Registers'))}</h2>${admin()?btn('Import data','import','upload'):''}</div><div class="modules">${Object.entries(modules).map(([k,m])=>{const st=stats(p.id,k)[0]||{},tot=st.total||0,closed=st.closed||0;return `<button class="module panel" data-category="${k}"><div class="row spread"><span class="stat-icon">${icon(m.icon)}</span><span class="card-arrow">${icon('arrow')}</span></div><div class="module-total">${n(tot)}</div><h3>${esc(mname(k))}</h3><div class="track" style="--pc:#9aafd8"><i style="width:${tot?100*closed/tot:0}%"></i></div><p>${n((st.open||0)+(st.review||0))} ${esc(t('Open + under review'))} · ${n(closed)} ${esc(t('Closed'))}</p></button>`}).join('')}</div>`;}
async function recordsContent(){const ticket=++recordsTicket,p=project();if(!p)return '';let q=db.from('records').select('id,project_id,category,reference,title,status,state,discipline,owner,due_date,occurred_on,revision,is_current,version,updated_at',{count:'exact'}).eq('project_id',p.id).eq('category',S.category).order('reference').order('revision');if(S.currentOnly)q=q.eq('is_current',true);if(S.recordState)q=q.eq('state',S.recordState);if(S.recordSearch){const search=S.recordSearch.replace(/[%_(),"\\]/g,' ').trim().slice(0,100);if(search)q=q.or(`reference.ilike.%${search}%,title.ilike.%${search}%,owner.ilike.%${search}%`);}const {data,error,count}=await q.range(S.recordPage*30,S.recordPage*30+29);if(error)throw Error(error.message);if(ticket!==recordsTicket)return null;S.records=data;S.recordCount=count||0;return recordsHTML();}
function recordsHTML(){return `<div class="section-head"><h2 class="section-title">${esc(mname(S.category))} <span class="pill">${n(S.recordCount)}</span></h2><div class="row wrap">${btn('Export CSV','export','download')}${admin()?btn('Import data','import','upload')+btn('Add record','add-record','plus','primary'):''}</div></div><div class="row filter-controls wrap" style="margin-bottom:18px"><select id="register-select" class="input" style="width:210px" aria-label="${t('Select register')}">${Object.keys(modules).map(k=>`<option value="${k}" ${S.category===k?'selected':''}>${esc(mname(k))}</option>`).join('')}</select><div class="searchbox grow">${icon('search')}<input id="record-search" style="width:100%;height:42px" placeholder="${t('Search records…')}" aria-label="${t('Search records…')}" value="${esc(S.recordSearch)}"></div><select class="input" id="record-state" style="width:145px" aria-label="${t('Status')}"><option value="">${t('All')}</option>${Object.entries(stateNames).map(([k,v])=>`<option value="${k}" ${S.recordState===k?'selected':''}>${esc(t(v))}</option>`).join('')}</select><label class="check-inline"><input id="current-only" type="checkbox" ${S.currentOnly?'checked':''}>${esc(t('Current revisions only'))}</label></div><div class="panel table-panel">${S.records.length?`<div class="table-wrap"><table class="responsive"><thead><tr>${['Reference','Status','Discipline','Owner','Due date'].map(l=>`<th>${esc(t(l))}</th>`).join('')}</tr></thead><tbody>${S.records.map(r=>`<tr data-record="${r.id}" tabindex="0"><td><strong>${esc(r.reference)}${r.revision?` <span class="pill">${esc(r.revision)}</span>`:''}</strong><span class="desc">${esc(r.title)}</span></td><td data-label="${t('Status')}">${statusPill(r.state,r.status)}</td><td data-label="${t('Discipline')}">${esc(r.discipline||'—')}</td><td data-label="${t('Owner')}">${esc(r.owner||'—')}</td><td data-label="${t('Due date')}">${esc(r.due_date?date(r.due_date):'—')}</td></tr>`).join('')}</tbody></table></div>`:empty('No records yet','This register is ready for your first update.','file')}<div class="pagination"><span>${n(S.recordCount?S.recordPage*30+1:0)}–${n(Math.min((S.recordPage+1)*30,S.recordCount))} / ${n(S.recordCount)} ${t('rows')}</span><div class="row"><button class="btn" data-action="prev-records" ${S.recordPage===0?'disabled':''}>${t('Previous')}</button><button class="btn" data-action="next-records" ${(S.recordPage+1)*30>=S.recordCount?'disabled':''}>${t('Next')}</button></div></div></div>`;}
async function progressContent(p){const rows=await check(db.from('project_updates').select('*').eq('project_id',p.id).order('as_of'));S.history=rows;let chart='';if(rows.length>1){const width=600,height=180,pad=22,points=rows.map((r,i)=>[pad+i*(width-2*pad)/(rows.length-1),height-pad-Number(r.actual||0)*(height-2*pad)/100]);chart=`<section class="panel panel-pad" style="margin-bottom:22px"><div class="section-head"><h2>${t('Progress history')}</h2><span class="pill">${t('Actual')} %</span></div><svg class="trend-chart" viewBox="0 0 600 180" role="img" aria-label="Progress trend">${[0,25,50,75,100].map(v=>`<line x1="22" y1="${height-pad-v*(height-2*pad)/100}" x2="578" y2="${height-pad-v*(height-2*pad)/100}" stroke="#eef0f6"/><text x="2" y="${height-pad-v*(height-2*pad)/100-3}" font-size="8" fill="#a1aec5">${v}</text>`).join('')}<polyline points="${points.map(x=>x.join(',')).join(' ')}" fill="none" stroke="#9bacdb" stroke-width="2.5"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="3" fill="#8196cc"><title>${esc(date(rows[i].as_of)+' '+pct(rows[i].actual))}</title></circle>`).join('')}</svg><div class="row spread small muted"><span>${esc(date(rows[0].as_of))}</span><span>${esc(date(rows.at(-1).as_of))}</span></div></section>`;}return chart+(rows.length?`<div class="panel table-panel"><div class="table-wrap"><table class="responsive"><thead><tr>${['Update date','Actual','Planned','Notes'].map(v=>`<th>${t(v)}</th>`).join('')}</tr></thead><tbody>${[...rows].reverse().map(r=>`<tr><td><strong>${esc(date(r.as_of))}</strong></td><td data-label="${t('Actual')}">${esc(pct(r.actual))}</td><td data-label="${t('Planned')}">${esc(pct(r.planned))}</td><td data-label="${t('Notes')}" style="white-space:pre-wrap;line-height:1.8">${esc(r.note)}</td></tr>`).join('')}</tbody></table></div></div>`:empty('No progress history yet','Post a dated update to start the trend.','chart'));}
function insights(){const ps=S.projects.filter(p=>!p.archived);return hero('Quality at a glance','Current register status')+`<div class="stats">${statCard('Register records',n(sum(S.stats,'total')),'Current revisions only','file')}${statCard('Open RFIs',n(statVal(null,'site_rfi')),'Current register status','eye')}${statCard('Open punch items',n(statVal(null,'punch')),'Current register status','list')}${statCard('Overdue items',n(sum(S.stats,'overdue')),'Open + under review','calendar')}</div><div class="insight-grid"><section class="panel panel-pad"><div class="section-head"><h2>${t('By register')}</h2><span class="pill">${t('Open + under review')}</span></div><div class="distribution">${Object.keys(modules).map(k=>{const total=statVal(null,k,'total'),op=statVal(null,k)+statVal(null,k,'review');return `<div class="distribution-line"><span>${esc(mname(k))}</span><div class="track" style="--pc:#a9b6df"><i style="width:${total?100*op/total:0}%"></i></div><b>${n(op)}</b></div>`}).join('')}</div></section><section class="panel panel-pad"><div class="section-head"><h2>${t('By project')}</h2><span class="pill">${t('Actual')} %</span></div>${ps.length?progressChart(ps):empty('No projects available','Your administrator will grant access to your projects.')}<div class="soft-divider"></div><div class="distribution">${ps.map(p=>`<button class="distribution-line" data-project="${p.id}"><span>${esc(p.code)}</span><div class="track" style="--pc:${color(p.color)}"><i style="width:${Number(p.actual)||0}%"></i></div><b>${esc(pct(p.actual))}</b></button>`).join('')}</div></section></div>`;}
async function usersContent(){[S.users,S.members]=await Promise.all([check(db.from('profiles').select('*').order('created_at')),check(db.from('project_memberships').select('*'))]);return hero('User management','Only administrators can create users and manage access.',btn('Create user','create-user','plus','primary'),'Administration')+`<div class="notice">${icon('shield')}${t('Users can view their assigned projects, but cannot edit data.')}</div><div class="panel table-panel"><div class="table-wrap"><table class="responsive"><thead><tr>${['Username','Full name','Status','Project access','Administration'].map(l=>`<th>${esc(t(l))}</th>`).join('')}</tr></thead><tbody>${S.users.map(u=>{const mem=S.members.filter(m=>m.user_id===u.id),codes=mem.map(m=>S.projects.find(p=>p.id===m.project_id)?.code).filter(Boolean);return `<tr><td><strong>${esc(u.username)}</strong><span class="small muted">${esc(t(u.role==='admin'?'Administrator':'Viewer'))}</span></td><td data-label="${t('Full name')}">${esc(u.full_name||'—')}</td><td data-label="${t('Status')}"><span class="pill ${u.active?'green':'red'}">${esc(t(u.active?'Enabled':'Disabled'))}</span></td><td data-label="${t('Project access')}">${u.role==='admin'?t('All project access'):codes.length?codes.map(c=>`<span class="pill blue" style="margin:2px">${esc(c)}</span>`).join(''):t('No project access')}</td><td data-label="${t('Administration')}"><div class="row wrap">${u.role!=='admin'?`<button class="btn icon" data-user-access="${u.id}" title="${t('Manage access')}">${icon('shield')}</button><button class="btn icon" data-user-toggle="${u.id}" title="${t(u.active?'Disable':'Enable')}">${icon(u.active?'lock':'check')}</button>`:''}<button class="btn icon" data-user-password="${u.id}" title="${t('Reset password')}">${icon('edit')}</button></div></td></tr>`}).join('')}</tbody></table></div></div>`;}
async function activityContent(){const rows=await check(db.from('audit_log').select('*').order('created_at',{ascending:false}).limit(100));return hero('Activity log','Latest updates','','Administration')+`<div class="notice">${icon('history')}${lang==='ar'?'آخر 100 تغيير. تسجيل التغييرات الجديدة بدأ مع هذه المساحة، وليس مع ملفات المصدر القديمة.':'Latest 100 changes. Activity tracking starts with this workspace, not with the imported source files.'}</div><div class="panel table-panel">${rows.length?`<div class="table-wrap"><table class="responsive"><thead><tr><th>${t('Update date')}</th><th>${t('Profile')}</th><th>${t('Description')}</th><th>${t('Reference')}</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(new Date(r.created_at).toLocaleString(lang==='ar'?'ar-AE':'en-GB'))}</strong></td><td data-label="${t('Profile')}">${esc(r.actor_id===S.profile.id?S.profile.username:(S.users.find(u=>u.id===r.actor_id)?.username||'Admin'))}</td><td data-label="${t('Description')}">${esc(r.action.toLowerCase().replaceAll('_',' '))} · ${esc(r.entity)}</td><td data-label="${t('Reference')}">${esc(r.label||'—')}</td></tr>`).join('')}</tbody></table></div>`:empty('No recent activity','Updates will appear here.','history')}</div>`;}
async function workloadPage(){
 const selected=S.projects.find(p=>p.id===S.workloadProject)||null;
 if(!selected)S.workloadProject='';
 const controls=`<section class="panel panel-pad workload-filters"><label class="field"><span>${esc(t('Select project'))}</span><select id="workload-project">${[['',t('All visible projects')],...S.projects.map(p=>[p.id,p.code+' · '+p.name])].map(([id,label])=>`<option value="${esc(id)}" ${id===(selected?.id||'')?'selected':''}>${esc(label)}</option>`).join('')}</select></label><p class="muted small">${esc(t('For assigned projects'))}</p></section>`;
 const help=admin()?`<div class="notice">${icon('upload')}<span>${esc(t('Import Site RFIs using the standard template. Set owner to the inspector name and occurred_on to the inspection date (YYYY-MM-DD). Current revisions are counted in the selected 30-day window.'))}</span></div>`:'';
 return hero('Inspector Workload','Inspection activity across your visible projects.',btn('Refresh','refresh','refresh')+(admin()&&S.projects.length?btn('Import data','workload-import','upload','primary'):''))+controls+help+await workloadContent(selected);
}
async function workloadContent(p=null){const end=S.workloadEnd||today();const rows=await check(db.rpc('inspection_workload',{p_project:p?.id||null,end_date:end}));const max=Math.max(1,...rows.map(x=>x.inspections));return `<div class="section-head"><div><h2 class="section-title">${esc(t('Inspector Workload'))}</h2><small>${lang==='ar'?'30 يوما حتى التاريخ المحدد، المراجعات الحالية فقط.':'30 days through the selected date, current revisions only.'}</small></div><label class="field"><span>${t('Reporting date')}</span><input type="date" id="workload-end" value="${esc(end)}"></label></div><div class="notice">${icon('eye')}${lang==='ar'?'الفحوصات محسوبة حسب تاريخ الفحص المسجل. الحالات المعروضة هي آخر حالة في المصدر، وليست إعادة بناء للحالة التاريخية.':'Inspections are grouped by recorded inspection date. Status counts use the latest source status, not a reconstruction of historical status.'}</div><section class="panel panel-pad">${rows.length?`<div class="distribution" style="margin-bottom:25px">${rows.slice(0,12).map(r=>`<div class="distribution-line" style="grid-template-columns:minmax(100px,190px) 1fr 40px"><span>${esc(r.inspector)}</span><div class="track" style="--pc:#9cacd8"><i style="width:${100*r.inspections/max}%"></i></div><b>${n(r.inspections)}</b></div>`).join('')}</div><p class="small muted" style="margin-bottom:16px">${esc(t('Up to 40 inspectors, ranked by inspection count.'))}</p><div class="table-wrap"><table class="responsive"><thead><tr>${(lang==='ar'?['المفتش','الفحوصات','أيام العمل','لكل يوم نشط','مفتوح الآن']:['Inspector','Inspections','Active days','Per active day','Currently open']).map(l=>`<th>${l}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.inspector)}</strong></td><td data-label="${lang==='ar'?'الفحوصات':'Inspections'}">${n(r.inspections)}</td><td data-label="${lang==='ar'?'أيام العمل':'Active days'}">${n(r.active_days)}</td><td data-label="${lang==='ar'?'لكل يوم نشط':'Per active day'}">${n(r.per_active_day)}</td><td data-label="${t('Open')}">${n(r.open)}</td></tr>`).join('')}</tbody></table></div>`:empty('No records yet',lang==='ar'?'جرب تاريخ تقرير آخر.':'Try another reporting date.','users')}</section>`;}
async function render(){if(!S.profile)return login();const ticket=++renderTicket;let content='';try{if(S.project){const p=project();if(!p){S.project=null;return render()}content=projectHeader(p);if(S.tab==='records')content+=(await recordsContent())||'';else if(S.tab==='progress')content+=await progressContent(p);else if(S.tab==='workload')content+=await workloadContent(p);else content+=projectOverview(p);}else if(S.page==='overview'||S.page==='projects')content=portfolio(S.page==='projects');else if(S.page==='insights')content=insights();else if(S.page==='workload')content=await workloadPage();else if(S.page==='users'&&admin())content=await usersContent();else if(S.page==='activity'&&admin())content=await activityContent();else{S.page='overview';content=portfolio()}if(ticket!==renderTicket)return;$('#app').innerHTML=shell(content);bindInputs();}catch(e){toast(e.message,true)}}
function bindInputs(){let timer;$('#workload-project')?.addEventListener('change',e=>{S.workloadProject=e.target.value;render()});$('#workload-end')?.addEventListener('change',e=>{S.workloadEnd=e.target.value;render()});const ps=$('#project-search');if(ps)ps.oninput=e=>{S.search=e.target.value;clearTimeout(timer);timer=setTimeout(async()=>{const pos=e.target.selectionStart;await render();const el=$('#project-search');el?.focus();el?.setSelectionRange(pos,pos)},200)};$('#project-filter')?.addEventListener('change',e=>{S.filter=e.target.value;render()});$('#register-select')?.addEventListener('change',e=>{S.category=e.target.value;S.recordPage=0;S.recordSearch='';render()});$('#record-state')?.addEventListener('change',e=>{S.recordState=e.target.value;S.recordPage=0;render()});$('#current-only')?.addEventListener('change',e=>{S.currentOnly=e.target.checked;S.recordPage=0;render()});$('#record-search')?.addEventListener('input',e=>{S.recordSearch=e.target.value;S.recordPage=0;clearTimeout(timer);timer=setTimeout(async()=>{const pos=e.target.selectionStart;await render();const el=$('#record-search');el?.focus();el?.setSelectionRange(pos,pos)},350)});}
function projectDialog(p=null){const body=`<div class="form-grid">${field('Project code','code',p?.code||'','text','required maxlength="50"')}${field('Project number','number',p?.number||'','text','maxlength="100"')}${field('Project name','name',p?.name||'','text','required maxlength="400" full')}${field('Contractor','contractor',p?.contractor||'','text','maxlength="200"')}${field('Contract','contract',p?.contract||'','text','maxlength="100"')}${field('Stage','stage',p?.stage||'Active','text','required maxlength="120"')}${field('Color','color',color(p?.color||'#879acc'),'color')}${field('Actual','actual',p?.actual??'','number','min="0" max="100" step="0.01"')}${field('Planned','planned',p?.planned??'','number','min="0" max="100" step="0.01"')}${field('Reporting date','as_of',p?.as_of||today(),'date','required')}${p?`<label class="check-inline"><input type="checkbox" name="archived" ${p.archived?'checked':''}>${t('Archive project')}</label>`:''}${textfield('Notes','note',p?.note||'','maxlength="5000"')}</div>${actions('Save project')}`;modal(p?'Edit project':'New project','Data stays linked to its project.',body,async(f,w)=>{const payload=Object.fromEntries(f);payload.actual=f.get('actual')===''?null:Number(f.get('actual'));payload.planned=f.get('planned')===''?null:Number(f.get('planned'));payload.archived=f.has('archived');payload.code=payload.code.trim().toUpperCase();if(!payload.code||!payload.name.trim())throw Error('Project code and name are required.');const query=p?db.from('projects').update(payload).eq('id',p.id).eq('updated_at',p.updated_at).select():db.from('projects').insert(payload).select();const rows=await check(query);if(!rows.length)throw Error('This project changed. Refresh and try again.');await loadData();w.close();toast('Saved');await render();});}
async function showRecord(id){const r=await check(db.from('records').select('*').eq('id',id).single());const basic=[['Reference',r.reference],['Description',r.title],['Status',r.status],['Discipline',r.discipline],['Owner',r.owner],['Due date',r.due_date?date(r.due_date):'—'],['Inspection / issue date',r.occurred_on?date(r.occurred_on):'—'],['Revision',r.revision||'—']];const body=`<div class="detail-list">${basic.map(([k,v])=>`<dl class="detail-item ${k==='Description'?'full':''}"><dt>${esc(t(k))}</dt><dd>${esc(v||'—')}</dd></dl>`).join('')}</div>${Object.keys(r.payload||{}).length?`<div class="soft-divider"></div><h3>${t('Source data')}</h3><div class="detail-list">${Object.entries(r.payload).filter(([k])=>!k.startsWith('_')).map(([k,v])=>`<dl class="detail-item ${String(v).length>100?'full':''}"><dt>${esc(k.replaceAll('_',' '))}</dt><dd>${esc(typeof v==='object'?JSON.stringify(v):v??'—')}</dd></dl>`).join('')}</div>`:''}<div class="form-actions"><button type="button" class="btn" data-close>${t('Cancel')}</button>${admin()?`<button type="button" class="btn primary" id="edit-this-record">${icon('edit')}${t('Edit record')}</button>`:''}</div>`;const w=modal('Record details',mname(r.category)+' · '+project().code,body,null,true);$('#edit-this-record',w)?.addEventListener('click',()=>{w.close();recordDialog(r)});}
function recordDialog(r=null){const body=`<div class="form-grid">${field('Reference','reference',r?.reference||'','text','required maxlength="500"')}${field('Revision','revision',r?.revision||'','text','maxlength="40"')}${field('Description','title',r?.title||'','text','required maxlength="3000" full')}${field('Status','status',r?.status||'Open','text','required maxlength="150"')}${select('Status','state',Object.entries(stateNames),r?.state||'open')}${field('Discipline','discipline',r?.discipline||'','text','maxlength="200"')}${field('Owner','owner',r?.owner||'','text','maxlength="200"')}${field('Due date','due_date',r?.due_date||'','date')}${field('Inspection / issue date','occurred_on',r?.occurred_on||'','date')}<label class="check-inline"><input type="checkbox" name="is_current" ${!r||r.is_current?'checked':''}>${t('Current revision')}</label>${textfield('Additional fields (JSON)','payload',JSON.stringify(r?.payload||{},null,2))}</div>${actions('Save record',r?`<button type="button" class="btn danger" id="delete-this-record">${t('Delete record')}</button>`:'')}`;const w=modal(r?'Edit record':'Add record',project().code+' · '+mname(S.category),body,async(f,w)=>{const data=Object.fromEntries(f);data.is_current=f.has('is_current');data.project_id=S.project;data.category=S.category;for(const k of ['due_date','occurred_on'])if(!data[k])data[k]=null;try{data.payload=JSON.parse(data.payload)}catch{throw Error('Additional fields must be valid JSON.')}if(!data.payload||Array.isArray(data.payload)||typeof data.payload!=='object')throw Error('Additional fields must be a JSON object.');if(JSON.stringify(data.payload).length>50000)throw Error('Additional fields are too large.');data.reference=data.reference.trim();if(!data.reference)throw Error('A reference is required.');const rows=await check(r?db.from('records').update(data).eq('id',r.id).eq('version',r.version).select('id'):db.from('records').insert(data).select('id'));if(!rows.length)throw Error('This record changed. Reopen it to see the latest version.');w.close();await loadData();toast('Saved');await render();},true);$('#delete-this-record',w)?.addEventListener('click',()=>{modal('Delete record',lang==='ar'?'لا يمكن التراجع عن الحذف. يمكنك تصدير السجل أولا.':'This cannot be undone. Export the register first if you need a backup.',`<p class="small muted">${esc(r.reference)}</p>${actions('Delete')}`,async(_,confirm)=>{const rows=await check(db.from('records').delete().eq('id',r.id).eq('version',r.version).select('id'));if(!rows.length)throw Error('This record changed. Reopen it before deleting.');confirm.close();w.close();await loadData();toast('Deleted');render()})});}
function progressDialog(){const p=project();modal('Post update',p.code,`<div class="form-grid">${field('Update date','as_of',today(),'date','required')}${field('Actual','actual',p.actual??'','number','required min="0" max="100" step="0.01"')}${field('Planned','planned',p.planned??'','number','min="0" max="100" step="0.01"')}${textfield('Notes','note','','required maxlength="5000"')}</div><div class="notice" style="margin-top:18px">${icon('history')}${lang==='ar'?'التحديث يحفظ في السجل. أحدث تاريخ تقرير يحدد نسبة التقدم الظاهرة على كارت المشروع.':'Every update is saved in the history. The latest reporting date sets the progress shown on the project card.'}</div>${actions('Publish update')}`,async(f,w)=>{await check(db.rpc('publish_progress',{pid:p.id,entry_date:f.get('as_of'),actual_pct:Number(f.get('actual')),planned_pct:f.get('planned')===''?null:Number(f.get('planned')),entry_note:f.get('note')}));w.close();await loadData();toast('Saved');render();});}
async function edge(body){const {data,error}=await db.functions.invoke('manage-users',{body});if(error){let msg=error.message;try{const b=await error.context.json();msg=b.error||msg}catch{}throw Error(msg)}if(data?.error)throw Error(data.error);return data;}
function createUserDialog(){modal('Create user','Users can view their assigned projects, but cannot edit data.',`<div class="form-grid">${field('Username','username','','text','required pattern="[a-z0-9][a-z0-9._-]{2,39}" maxlength="40" autocomplete="off" autocapitalize="none" spellcheck="false"')}${field('Full name','full_name','','text','required maxlength="160"')}${field('Password','password','','password','required minlength="12" maxlength="128" autocomplete="new-password" full')}</div><div class="notice" style="margin-top:20px">${icon('lock')}${lang==='ar'?'استخدم كلمة مرور 12 حرفا على الأقل. الحساب يبدأ بلا صلاحيات مشاريع. بعد الإنشاء حدد المشاريع المتاحة له.':'Use at least 12 characters. New users start with no project access. Assign their projects after creating the account.'}</div>${actions('Create account')}`,async(f,w)=>{const result=await edge({action:'create',...Object.fromEntries(f)});$('form',w).reset();w.close();toast('Created');await render();const user=S.users.find(u=>u.id===result.id);if(user)accessDialog(user);});}
function accessDialog(u){const existing=S.members.filter(m=>m.user_id===u.id).map(m=>m.project_id);modal('Project access','Choose the projects this user can see. Changes apply on their next request.',`<h3 style="margin-bottom:18px">${esc(u.full_name||u.username)} <span class="muted small">@${esc(u.username)}</span></h3><div class="permissions-list">${S.projects.map(p=>`<label class="check-row"><input type="checkbox" name="projects" value="${p.id}" ${existing.includes(p.id)?'checked':''}><span><strong>${esc(p.code)}${p.archived?' · '+t('Archived'):''}</strong>${esc(p.name)}</span></label>`).join('')}</div>${actions('Save access')}`,async(f,w)=>{await check(db.rpc('set_project_access',{target_user:u.id,allowed_projects:f.getAll('projects')}));w.close();toast('Saved');render();});}
function passwordDialog(u){modal('Set password',u.username,`<div class="form-grid">${field('New password','password','','password','required minlength="12" maxlength="128" autocomplete="new-password" full')}</div><div class="notice" style="margin-top:20px">${icon('lock')}${lang==='ar'?'12 حرفا على الأقل. شارك كلمة المرور بشكل آمن. لا يتم عرض كلمات المرور الحالية أو تخزينها في السجلات.':'Use at least 12 characters and share it securely. Existing passwords are never shown or written to activity logs.'}</div>${actions('Set password')}`,async(f,w)=>{await edge({action:'password',user_id:u.id,password:f.get('password')});$('form',w).reset();w.close();toast('Password updated');});}
function toggleUser(u){modal(u.active?'Disable':'Enable',u.username,`<p class="small muted">${lang==='ar'?'تعطيل الحساب يوقف الوصول لكل بيانات المشاريع.':'Disabling the account blocks access to all project data.'}</p>${actions(u.active?'Disable':'Enable')}`,async(_,w)=>{await edge({action:'active',user_id:u.id,active:!u.active});w.close();toast('Saved');render()});}
function accountDialog(){modal('Your account',S.profile.username,`<div class="detail-list"><dl class="detail-item"><dt>${t('Full name')}</dt><dd>${esc(S.profile.full_name)}</dd></dl><dl class="detail-item"><dt>${t('Profile')}</dt><dd>${t(admin()?'Administrator':'Viewer')}</dd></dl></div><div class="form-actions">${admin()?`<button type="button" class="btn" id="own-password">${t('Change password')}</button>`:''}<button type="button" class="btn danger" data-action="logout">${icon('logout')}${t('Sign out')}</button></div>`,null);$('#own-password')?.addEventListener('click',()=>{$('.modal-backdrop')?.remove();passwordDialog(S.profile)});}
function download(name,data,type='text/csv;charset=utf-8'){const blob=new Blob([data],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)}
function csv(rows,columns){const safe=v=>{let s=typeof v==='object'?JSON.stringify(v):String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};return '\ufeff'+[columns.map(safe).join(','),...rows.map(r=>columns.map(k=>safe(r[k])).join(','))].join('\r\n')}
const importCols=['reference','title','status','state','discipline','owner','due_date','occurred_on','revision','is_current','payload'];
async function exportRecords(){toast(lang==='ar'?'جار تجهيز التصدير…':'Preparing export…');let rows=[],offset=0;while(true){let q=db.from('records').select(importCols.join(',')).eq('project_id',S.project).eq('category',S.category).order('id').range(offset,offset+999);if(S.currentOnly)q=q.eq('is_current',true);if(S.recordState)q=q.eq('state',S.recordState);if(S.recordSearch){const search=S.recordSearch.replace(/[%_(),"\\]/g,' ').trim().slice(0,100);if(search)q=q.or(`reference.ilike.%${search}%,title.ilike.%${search}%,owner.ilike.%${search}%`)}const data=await check(q);rows.push(...data);if(data.length<1000)break;offset+=1000;if(offset>100000)throw Error('Export too large. Use project/register filters.')}download(project().code+'-'+S.category+'.csv',csv(rows,importCols));toast(lang==='ar'?'تم تصدير '+n(rows.length)+' صف':'Exported '+n(rows.length)+' rows');}
async function importDialog({projectId=S.project,category=S.category}={}){const ps=S.projects;let prepared=[],errors=[];const w=modal('Import data','Data stays linked to its project.',`<div class="form-grid">${select('Select project','project',ps.map(p=>[p.id,p.code+' · '+p.name]),projectId||ps[0]?.id)}${select('Select register','category',Object.keys(modules).map(k=>[k,mname(k)]),category)}</div><div class="notice" style="margin-top:18px">${icon('file')}<span>${lang==='ar'?'استعمل القالب الموحد. الحد الأقصى 5000 صف و5 ميجابايت. لا يتم نشر أي بيانات قبل مراجعة المعاينة والضغط على استيراد.':'Use the standard template. Maximum 5,000 rows and 5 MB. Nothing is saved until you review the preview and choose Import records.'}</span></div><button type="button" class="btn" id="download-template">${icon('download')}${t('Download template')}</button><div class="file-drop">${icon('upload')}<h3>${t('Choose a CSV or Excel file')}</h3><p>${lang==='ar'?'الحقول المطلوبة: reference, title. التواريخ بصيغة YYYY-MM-DD.':'Required columns: reference, title. Dates use YYYY-MM-DD. Existing reference + revision rows are updated; other rows are added.'}</p><input type="file" id="import-file" accept=".csv,.xlsx" aria-label="${t('Choose file')}"></div><div id="import-preview"></div><div class="progress-message" id="import-progress" role="status"></div><div class="form-actions"><button type="button" class="btn" data-close>${t('Cancel')}</button><button type="submit" class="btn primary" disabled id="confirm-import">${t('Import records')}</button></div>`,async(f,w,form)=>{if(!prepared.length||errors.length)throw Error('Choose a valid file first.');const pid=f.get('project'),cat=f.get('category'),submit=$('#confirm-import',w),progress=$('#import-progress',w);$$('input,select,button',w).forEach(el=>el.disabled=true);let saved=0;try{for(let i=0;i<prepared.length;i+=100){const batch=prepared.slice(i,i+100).map(r=>({...r,project_id:pid,category:cat}));await check(db.from('records').upsert(batch,{onConflict:'project_id,category,reference,revision'}));saved+=batch.length;progress.textContent=(lang==='ar'?'تم حفظ ':'Saved ')+n(saved)+' / '+n(prepared.length);}w.close();await loadData();toast(lang==='ar'?'تم استيراد '+n(saved)+' صف':'Imported '+n(saved)+' rows');render()}catch(e){progress.textContent=(lang==='ar'?'حفظ ':'Saved ')+n(saved)+' / '+n(prepared.length)+'. '+(lang==='ar'?'قد يكون الاستيراد جزئيا. إعادة نفس الملف تحدث الصفوف دون تكرارها.':'Import may be partial. Re-importing the same file updates matching rows without duplicating them.');throw e}finally{$$('input,select,button',w).forEach(el=>el.disabled=false)}},true);
 $('#download-template',w).onclick=()=>download('quality-hub-import-template.csv',csv([{reference:'EXAMPLE-001',title:'Example record - replace before importing',status:'Open',state:'open',discipline:'Civil',owner:'',due_date:today(),occurred_on:today(),revision:'A',is_current:true,payload:{}}],importCols));
 $('#import-file',w).onchange=async e=>{prepared=[];errors=[];$('#confirm-import',w).disabled=true;const file=e.target.files[0],prev=$('#import-preview',w);prev.innerHTML='';if(!file)return;try{if(file.size>5*1024*1024)throw Error('File exceeds 5 MB. Split it into smaller files.');const XLSX=await import('xlsx');const book=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true,raw:true});const raw=XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]],{defval:''});if(!raw.length)throw Error('The first worksheet is empty.');if(raw.length>5000)throw Error('Use no more than 5,000 rows per import.');const seen=new Set();const validDate=v=>{if(!v)return null;if(v instanceof Date)return [v.getFullYear(),String(v.getMonth()+1).padStart(2,'0'),String(v.getDate()).padStart(2,'0')].join('-');let s=String(v).trim();if(!/^\d{4}-\d{2}-\d{2}$/.test(s)||!Number.isFinite(Date.parse(s))||new Date(s).toISOString().slice(0,10)!==s)throw Error('Use dates as YYYY-MM-DD');return s};raw.forEach((r,i)=>{try{let x={};for(let [k,v]of Object.entries(r))x[k.trim().toLowerCase()]=v;const reference=String(x.reference||'').trim(),title=String(x.title||'').trim();if(!reference||!title)throw Error('reference and title are required');if(reference.length>500||title.length>3000)throw Error('reference or title is too long');const revision=String(x.revision??'').trim(),key=reference+'|'+revision;if(seen.has(key))throw Error('Duplicate reference and revision in this file');seen.add(key);const state=String(x.state||'open').trim().toLowerCase();if(!stateNames[state])throw Error('state must be open, closed, review, void, superseded or other');let payload=x.payload?JSON.parse(String(x.payload)):{};if(!payload||Array.isArray(payload)||typeof payload!=='object')throw Error('payload must be a JSON object');prepared.push({reference,title,revision,state,status:String(x.status||stateNames[state]),discipline:String(x.discipline||''),owner:String(x.owner||''),due_date:validDate(x.due_date),occurred_on:validDate(x.occurred_on),is_current:!['false','0','no'].includes(String(x.is_current).toLowerCase()),payload});}catch(err){errors.push('Row '+(i+2)+': '+err.message)}});prev.innerHTML=`<div class="soft-divider"></div><div class="section-head"><h3>${t('Import preview')}</h3><span class="pill ${errors.length?'red':'green'}">${n(prepared.length)} ${t('rows')} · ${n(errors.length)} ${lang==='ar'?'أخطاء':'errors'}</span></div>${errors.length?`<div class="form-error">${errors.slice(0,8).map(esc).join('<br>')}</div>`:''}<div class="table-wrap"><table><thead><tr><th>${t('Reference')}</th><th>${t('Description')}</th><th>${t('Status')}</th></tr></thead><tbody>${prepared.slice(0,5).map(r=>`<tr><td>${esc(r.reference)}</td><td>${esc(r.title.slice(0,100))}</td><td>${esc(r.status)}</td></tr>`).join('')}</tbody></table></div><p class="small muted" style="margin-top:12px">${lang==='ar'?'تعرض المعاينة أول خمسة صفوف. الصفوف ذات نفس المرجع والمراجعة سيتم استبدالها.':'Preview shows the first five rows. Matching reference + revision rows will be overwritten. Missing rows are not deleted.'}</p>`;$('#confirm-import',w).disabled=!!errors.length||!prepared.length;}catch(err){prev.innerHTML=`<div class="form-error">${esc(err.message)}</div>`}};
}
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-project],[data-record]')){e.preventDefault();e.target.click()}});
document.addEventListener('click',async e=>{const a=e.target.closest('[data-action],[data-page],[data-project],[data-tab],[data-category],[data-record],[data-user-access],[data-user-password],[data-user-toggle]');if(!a)return;try{if(a.dataset.page){S.page=a.dataset.page;S.project=null;S.search='';await render();window.scrollTo(0,0)}else if(a.dataset.project){S.project=a.dataset.project;S.page='projects';S.tab='overview';S.recordPage=0;S.recordSearch='';await render();window.scrollTo(0,0)}else if(a.dataset.tab){S.tab=a.dataset.tab;S.recordPage=0;await render();window.scrollTo(0,0)}else if(a.dataset.category){S.category=a.dataset.category;S.tab='records';S.recordPage=0;S.recordSearch='';S.recordState='';await render();window.scrollTo(0,0)}else if(a.dataset.record){await showRecord(a.dataset.record)}else if(a.dataset.userAccess){accessDialog(S.users.find(u=>u.id===a.dataset.userAccess))}else if(a.dataset.userPassword){passwordDialog(S.users.find(u=>u.id===a.dataset.userPassword))}else if(a.dataset.userToggle){toggleUser(S.users.find(u=>u.id===a.dataset.userToggle))}else switch(a.dataset.action){case'language':setLanguage();break;case'logout':await db.auth.signOut();S.profile=null;$('.modal-backdrop')?.remove();login();break;case'menu':$('.sidebar')?.classList.toggle('open');break;case'account':accountDialog();break;case'refresh':a.disabled=true;await loadData();await render();toast('Refreshed');break;case'new-project':if(admin())projectDialog();break;case'edit-project':if(admin())projectDialog(project());break;case'post-update':if(admin())progressDialog();break;case'back-projects':S.project=null;S.page='projects';render();break;case'grid-view':S.list=false;render();break;case'list-view':S.list=true;render();break;case'prev-records':S.recordPage=Math.max(0,S.recordPage-1);render();break;case'next-records':S.recordPage++;render();break;case'add-record':if(admin())recordDialog();break;case'export':await exportRecords();break;case'import':if(admin())await importDialog();break;case'workload-import':if(admin())await importDialog({projectId:S.workloadProject,category:'site_rfi'});break;case'create-user':if(admin())createUserDialog();break;}}catch(err){toast(err.message,true)}});
db.auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT'&&S.profile){S.profile=null;login(t('Session ended. Please sign in again.'))}});
document.addEventListener('visibilitychange',async()=>{if(!document.hidden&&S.profile){try{const profile=await check(db.from('profiles').select('*').eq('id',S.profile.id).single());if(!profile.active)throw Error('Disabled');S.profile=profile;await loadData();await render()}catch{await db.auth.signOut();S.profile=null;login(t('Your account is disabled. Contact your administrator.'))}}});
(async()=>{document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';const {data:{session}}=await db.auth.getSession();if(session)await enter();else login()})();
